{
  "title": "The Mirror's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a cracked map at the ruined city's edge.",
      "visual_description": "Mara the Cartographer stands before a fallen stone arch, unrolling a torn parchment map while the Oracle Lamp flickers beside her, casting long shadows over rubble.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver peers through a broken window into the city.",
      "visual_description": "Glass Diver presses his helmet against a shattered window pane, his reflection showing the ruined skyline beyond, while Tin Fox waits at his feet, tail ticking.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The group enters the castle gates, now rusted and partly collapsed.",
      "visual_description": "Massive iron gates hang askew, vines and rust covering the hinges; Mara steps through first, compass in hand, as Oracle Lamp glows warningly from her belt.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "A cursed tower looms ahead, its spire twisted and dark.",
      "visual_description": "A stone tower leans at an unnatural angle, its windows pulsing with faint violet light; Tin Fox sniffs the air and whirs backward.",
      "characters": ["tin_fox", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The Oracle Lamp warns of a trap within the tower's shadow.",
      "visual_description": "Oracle Lamp's single eye flares bright red as its flame sputters, casting a blood-red glow on Mara's worried face and the tower's crooked door.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "Old royal banners hang tattered from empty flagpoles.",
      "visual_description": "Faded banners with torn emblems flap in a cold wind above a cobbled square, their fabric moth-eaten and bleached by sun.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Frightened townspeople huddle behind boarded windows, watching.",
      "visual_description": "Through cracked shutters, pale faces peer out; a child's hand presses against a glass pane, while Mara gestures for silence.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrols march in the distance, their footsteps echoing.",
      "visual_description": "A column of figures in dented plate armor clanks across a bridge, their visors down, weapons glinting in the grey light.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector snores behind a desk in a ruined hall.",
      "visual_description": "Inside a half-collapsed building, the Sleeping Tax Collector sleeps with his head on a ledger, stamp still in hand, papers scattered around him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Mara tries to wake the Tax Collector for information.",
      "visual_description": "Mara shakes the Sleeping Tax Collector's shoulder, but he only mumbles and rolls over, a stamped paper stuck to his cheek.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The Glass Diver finds a magic door hidden behind a tapestry.",
      "visual_description": "Glass Diver pulls aside a moth-eaten tapestry to reveal a door etched with glowing runes, its surface rippling like water.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The group debates whether to open the magic door.",
      "visual_description": "Mara consults her map while Oracle Lamp flickers nervously; Tin Fox taps the door with a metal paw, making the runes pulse.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "They open the door to a long corridor of mirrors.",
      "visual_description": "The magic door swings open to reveal a hallway lined with full-length mirrors, each reflecting a different ruined vista; Glass Diver steps forward, fascinated.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The Glass Diver leads them through the mirror corridor.",
      "visual_description": "Glass Diver taps a mirror, which ripples like water; he swims through, followed by Tin Fox, while Mara and Oracle Lamp hesitate at the threshold.",
      "characters": ["glass_diver", "tin_fox", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "They emerge near a courtyard with the escape bridge in sight.",
      "visual_description": "The group steps out of a mirror onto a balcony overlooking a cobbled courtyard; beyond, a stone bridge arches over a dry moat, the exit visible.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols block the bridge, their formation tight.",
      "visual_description": "A phalanx of armored figures stands at the bridge's entrance, shields locked, spears pointed forward; the group hides behind a crumbling wall.",
      "characters": ["tin_fox", "oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The Glass Diver creates a distraction using a mirror.",
      "visual_description": "Glass Diver positions a broken mirror to reflect sunlight into the patrol's visors, blinding them momentarily, while Mara signals the group to move.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The group crosses the bridge and escapes the ruined city.",
      "visual_description": "Under the cover of the distraction, the group sprints across the bridge—Mara clutching her map, Glass Diver's helmet glinting, Tin Fox scuttling, and Oracle Lamp's flame streaming backward—as the city recedes behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    }
  ],
  "title": "The Mirror's Escape"
}

